sys_script.script:
(function executeRule(current, previous /* previous may be null for inserts */) {
  try {
    gs.info("[BR Debug] BR_Validate_SetFields start for: " + current.getTableName() + "/" + current.sys_id);

    // 1) Prevent 'When needed' being set to a past date (example date field: u_when_needed)
    if (!current.u_when_needed.nil()) {
      var whenNeeded = new GlideDateTime(current.u_when_needed);
      var now = new GlideDateTime();
      if (whenNeeded.before(now)) {
        gs.error("[BR Debug] u_when_needed is in the past: " + current.u_when_needed);
        gs.addErrorMessage("When needed cannot be in the past.");
        // abort the database operation
        current.setAbortAction(true);
        return;
      }
    }

    // 2) Auto-set requested_for (reference) to the current user if empty
    if (current.u_requested_for.nil()) {
      current.u_requested_for = gs.getUserID();
      gs.info("[BR Debug] Set u_requested_for to current user: " + gs.getUserID());
    }

    // 3) Copy short_description into description if description empty
    if (current.description.nil() && !current.short_description.nil()) {
      current.description = current.short_description;
      gs.info("[BR Debug] Copied short_description to description");
    }

  } catch (ex) {
    gs.error("[BR Debug] Exception in BR_Validate_SetFields: " + ex);
  }
})(current, previous);
